style.css:
@-moz-document domain("youtube.com"), domain("m.youtube.com"), domain("music.youtube.com") {
/* =========================================
       1. ÉP NỀN TỐI TOÀN BỘ TRANG (FORCE DARK BG)
       ========================================= */
    html, body, ytd-app, #content, #page-manager, #primary, #secondary, #columns {
        background-color: #0a0a14 !important;
        color: #ffffff !important;
    }

    /* Tạo lại hiệu ứng chấm bi fade trên nền đen */
    body {
        background-image: 
            linear-gradient(to bottom, #0a0a14 0%, rgba(10,10,20,0.85) 40%, rgba(10,10,20,0) 100%),
            radial-gradient(#a4e332 12%, transparent 13%),
            radial-gradient(#a4e332 12%, transparent 13%),
            linear-gradient(to bottom, #0a0a14, #1a0033) !important;
        background-size: 100% 100%, 26px 26px, 26px 26px, 100% 100% !important;
        background-position: 0 0, 0 0, 13px 13px, 0 0 !important;
        background-attachment: fixed !important;
    }

    /* =========================================
       2. ÉP KHUNG THẺ VIDEO & COMMENT SANG CARD TỐI
       ========================================= */
    ytd-rich-item-renderer,
    ytd-compact-video-renderer,
    ytd-comment-thread-renderer,
    ytd-comment-renderer,
    ytd-video-renderer {
        background-color: #121220 !important;
        border: 3px solid #00e5ff !important;
        border-radius: 16px !important;
        padding: 12px !important;
        margin-bottom: 16px !important;
        box-shadow: 4px 4px 0px #ff007f !important;
    }

    /* Ép màu chữ bên trong video và comment hiển thị màu trắng rõ nét */
    #video-title, 
    .ytd-video-meta-block, 
    #content-text,
    ytd-comment-renderer yt-formatted-string,
    span.yt-core-attributed-string,
    h1, h2, h3, h4 {
        color: #ffffff !important;
    }

    /* =========================================
       3. HEADER & THANH TÌM KIẾM
       ========================================= */
    #masthead, ytd-masthead {
        background: #ff007f !important;
        border-bottom: 4px solid #ffea00 !important;
        box-shadow: 0px 4px 0px #8a2be2 !important;
    }

    #container.ytd-searchbox {
        background-color: #ffffff !important;
        border: 3px solid #ffea00 !important;
        border-radius: 20px 0 0 20px !important;
    }
    
    input#search {
        color: #000000 !important;
        font-weight: bold !important;
    }

    #search-icon-legacy.ytd-searchbox {
        background: #ffea00 !important;
        border: 3px solid #ffea00 !important;
        border-radius: 0 20px 20px 0 !important;
    }
    
    #search-icon-legacy.ytd-searchbox yt-icon {
        color: #ff007f !important;
    }
}
